  ('utila-honduras', '10S', 'Utila', 'Honduras', 'Utila Honduras diving', 'live', 'verified', 'oceanAerial', 'Honduras', '{"liveaboard","tropical","expedition"}', '{"tropical"}', '{"essential","comfort"}', null, null, '{"key_facts":["World''s cheapest PADI/SSI Open Water cert (~US$280-350), free/discounted dorm while diving; 60+ dive sites on the Mesoamerican Barrier Reef (2nd-largest on Earth)","Whale sharks year-round (best Mar-May + Aug-Sep); snorkel-only from the surface - scuba diving WITH whale sharks is prohibited","Reached by air to Roatan (RTB) or San Pedro Sula (SAP) + ferry from La Ceiba (~1 hr, ~US$35, Utila Dream ferry - sole operator); Utila airstrip is private-charter only","Budget-to-boutique dive island; ceiling = dive-resort lodge (Utila Lodge 8 over-water rooms, Mango Inn); NO branded ultra on-island - Roatan/Guanaja hold the luxury tier","The Cays / Water Cay uninhabited white-sand sandbar (Sun Jam festival site); Utila Cays Garifuna fishing village (Jewel + Pigeon/Suc-Suc); Chepes Beach; endangered Utila spiny-tailed iguana station"],"safety":{"emergency":"911 (national police/fire/ambulance, Honduras - verify locally)","hyperbaric_chamber":"ON-ISLAND - Utila has its own chamber (at Utila Lodge, also doubling as island trauma center; a chamber also via Bay Islands College of Diving/College of Diving); a genuine asset most small dive islands lack","no_fly_after_diving":true,"hospital":"small clinics only + the Utila Lodge hyperbaric/trauma center on-island; serious trauma/complex dive cases route OFF-ISLAND to La Ceiba (mainland) then mainland hospital or US medevac; carry travel-medical + air-evac + DAN dive insurance","remote_flag":true,"l3_disclosure":true,"stay_in_zone":true,"air_access_verified":"RTB (Roatan) or SAP (San Pedro Sula) international arrival, then ferry to Utila from La Ceiba (~1 hr, ~US$35, Utila Dream ferry) or Roatan-Utila ferry; Utila airstrip = private charter only; routing never touches mainland gang zones","founder_policy_note":"keep client in-zone","reef_safety":"protected Mesoamerican marine reserve - no-touch/no-stand, reef-safe sunscreen; wall/deep-site currents; whale-shark no-touch/no-scuba boat protocol","dengue":"dengue occasionally reported on Utila - protect against daytime Aedes (DEET/picaridin)","sandfly":"sandflies/no-see-ums are the signature nuisance, most active dusk-to-dawn; standard DEET underperforms - use oil-based lotion (Skin So Soft), cover up, net/fan at night; bites rarely carry leishmaniasis","water":"tap water NOT potable - bottled/refill only; mind ice/raw produce; wash hands before eating","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/honduras","read":"2026-09-01T16:19:22Z","page_updated":"2026-07-29T16:40:19+01:00","source_country":"honduras","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely"},"timing":{"peak":"Dec-Apr (dry season; Christmas-New Year + Easter/Semana Santa sub-peaks)","whale_shark_subpeaks":"Mar-May and Aug-Sep (year-round presence; best odds; Aug-Sep is a green-season demand spike)","shoulder_green":"late-Oct-mid/late-Feb rains + Sep-Oct highest storm risk (value trough; but Sep is a whale-shark sub-peak); value island stays busy with cert traffic","out_of_season_fill_the_beds":"dive-cert value packages, Aug-Sep whale-shark spike at shoulder rates, freediving courses (weather-resilient), new-moon night dives, Cays day-trips between storms","fire_date":"dry-peak: early-to-mid November (curve-start late-Nov minus 1-2 wks); Mar-May whale-shark: mid-February; Aug-Sep whale-shark: mid-July; dive-cert stays book-short-lead with permanent rolling last-minute layer","flag":"whale-shark sightings are probabilistic - market ''best odds'' never a guarantee; sharpen dates on live booking-pace tracking","dive_calendar":true,"sources":["https://www.utilalodge.com/whale-shark-encounters","https://www.islaguru.com/articles/utila-travel-practical-guide","https://www.mango-inn.com/","https://www.freediveutila.com/"],"event_peaks":"Christmas-New Year, Easter/Semana Santa, Sun Jam (Water Cay, ~August - verify dates), whale-shark sub-peaks as de-facto events","booking_lead":"TWO SPEEDS - dive-cert/backpacker = short-lead (days-to-weeks, walk-in dorms, rolling last-minute layer); over-water dive-lodge tier + peak whale-shark weeks + Christmas/Easter = 2-4 months ahead"},"jewels":[{"name":"PADI/SSI Open Water certification (world''s cheapest)","timing":"Dec-Apr","tier":"essential","source":"https://utiladivecenter.com/","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","when":"Dec-Apr","commission":"dive-operator commission on application; CLIA dive-lane convert to commissioned agent","wells":["activities","stay"],"wells_basis":"full pass 2026-10-05, additive — text","blurb":"~US$280-350, free dorm while diving; the entry drug that turns a 3-day stop into a 3-week stay","blurb_note":"recovered from orphaned field `why` 2026-08-22","si_all":["liveaboard"],"shelf_fit":{"expedition":"destination","liveaboard":"primary","tropical":"destination"},"commission_lane":["operator"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Night dive - ''string of pearls'' bioluminescence (Ted''s Point / Ron''s Wreck)","timing":"Dec-Apr","tier":"essential","source":"https://www.dive-utila.com/advanced-open-water-diver","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","when":"Dec-Apr","commission":"dive-operator + CLIA lane","wells":["stay","activities"],"wells_basis":"derived from name/blurb/hook","blurb":"kill the lights on a new moon and watch ostracod bioluminescence flash through the water column; hunting octopus","blurb_note":"recovered from orphaned field `why` 2026-08-22","si_all":["liveaboard"],"shelf_fit":{"expedition":"destination","liveaboard":"primary","tropical":"destination"},"commission_lane":["operator"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Halliburton wreck + Airport Caves (deep/wall)","timing":"Dec-Apr","tier":"comfort","source":"https://www.dive-utila.com/advanced-open-water-diver","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","when":"Dec-Apr","commission":"dive-operator + CLIA lane","wells":["activities","fly"],"wells_basis":"full pass 2026-10-05, additive — text","blurb":"upright cargo-ship wreck ~30 m + cavern swim-throughs full of glassy sweepers - the reef''s set-pieces","blurb_note":"recovered from orphaned field `why` 2026-08-22","si_all":["liveaboard","tropical"],"shelf_fit":{"expedition":"destination","liveaboard":"primary","tropical":"evidenced"},"commission_lane":["operator"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Whale-shark snorkel expedition","timing":"year-round; peak odds Mar-May + Aug-Sep","tier":"comfort","source":"https://www.utilalodge.com/whale-shark-encounters","si":"expedition","when":"year-round; peak odds Mar-May + Aug-Sep","commission":"operator/expedition commission on application + Viator/GYG affiliate; CLIA-lane crossover","wells":["activities"],"wells_basis":"derived from name/blurb/hook","blurb":"snorkel beside the largest fish in the ocean, year-round; captains hunt the bait-ball boil + diving birds","blurb_note":"recovered from orphaned field `why` 2026-08-22","si_all":["expedition"],"shelf_fit":{"expedition":"primary","liveaboard":"destination","tropical":"destination"},"commission_lane":["operator","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Freediving course (Freedive Utila - Central America''s freediving HQ)","timing":"Dec-Apr","tier":"comfort","source":"https://www.freediveutila.com/","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","when":"Dec-Apr","commission":"course commission on application","wells":["activities"],"wells_basis":"derived from name/blurb/hook","blurb":"learn to fall through the blue on one breath at the region''s only competitive freediving cooperative","blurb_note":"recovered from orphaned field `why` 2026-08-22","si_all":["expedition"],"shelf_fit":{"expedition":"primary","liveaboard":"destination","tropical":"destination"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"Utila Iguana Station (endangered spiny-tailed ''swamper'' iguana)","timing":"Dec-Apr","tier":"essential","source":"https://www.islaguru.com/articles/things-to-do-utila-island-honduras","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","when":"Dec-Apr","commission":"non-commissionable conservation donation - value-add/character stop, not a margin line","wells":["activities"],"wells_basis":"full pass 2026-10-05, additive — default - a place to see or do (David 2026-10-05: fully integrated)","blurb":"conservation center for the iguana found only on Utila, living in its mangroves - a meaningful low-cost morning","blurb_note":"recovered from orphaned field `why` 2026-08-22","si_all":["expedition"],"shelf_fit":{"expedition":"primary","liveaboard":"destination","tropical":"destination"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"Water Cay (the Cays) day-trip","timing":"year-round, calm-day best; festival ~August","tier":"essential","source":"https://www.utilawatersport.com/water-cay","si":"tropical","when":"year-round, calm-day best; festival ~August","commission":"local boat/tour operator + Viator affiliate (marine-park fee non-commissionable)","wells":["activities"],"wells_basis":"derived from name/blurb/hook","blurb":"tiny uninhabited white-sand island + sandbar ringed by coral; snorkel-and-sandbar paradise; Sun Jam festival site","blurb_note":"recovered from orphaned field `why` 2026-08-22","si_all":["tropical"],"shelf_fit":{"expedition":"destination","liveaboard":"destination","tropical":"primary"},"commission_lane":["operator","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Utila Cays - Jewel Cay & Pigeon (Suc-Suc) Garifuna fishing village","timing":"Dec-Apr","tier":"essential","source":"https://www.utilaguide.com/activities/cays/","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"tropical","when":"Dec-Apr","commission":"local boat operator + F&B affiliate-adjacent","wells":["activities","stay"],"wells_basis":"full pass 2026-10-05, additive — text","blurb":"two cays joined by a footbridge, ~500 people on stilt homes over the water - a Garifuna/Caymanian fishing-village time capsule","blurb_note":"recovered from orphaned field `why` 2026-08-22","si_all":["tropical"],"shelf_fit":{"expedition":"destination","liveaboard":"destination","tropical":"primary"},"commission_lane":["operator","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Chepes Beach + Rehab bar","timing":"year-round","tier":"essential","source":"https://www.islaguru.com/articles/things-to-do-utila-island-honduras","si":"tropical","when":"year-round","commission":"F&B/OTA-adjacent scene-setter, not a margin line","wells":["activities"],"wells_basis":"full pass 2026-10-05, additive — text","blurb":"the island''s largest public beach - soft white sand, shallow calm water, beachfront bar; the free between-dives afternoon","blurb_note":"recovered from orphaned field `why` 2026-08-22","si_all":["tropical"],"shelf_fit":{"expedition":"destination","liveaboard":"destination","tropical":"primary"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"}],"faq":[{"q":"What''s the real risk to plan for?","a":"Two risks are load-bearing: mainland crime and island remoteness. Separately, serious trauma or complex dive injuries route off-island to La Ceiba then a mainland hospital or US medevac, so carry travel-medical, air-evac, and DAN dive insurance without exception.","source":"https://www.gov.uk/foreign-travel-advice/honduras","si_tag":"safety"},{"q":"Is learning to dive here dangerous, and can I fly out afterward?","a":"Diving here rewards a certified operator and disciplined profiles, and Utila has an unusual on-island safety asset. Certify only with a PADI/SSI-certified shop (UDC, Alton''s, Parrots, College of Diving, Underwater Vision), dive within no-decompression limits, and observe no-fly-after-diving of 18–24 hours before flying. Utila has its own hyperbaric chamber at Utila Lodge (doubling as the island trauma center), with a chamber also via Bay Islands College of Diving — a genuine asset most small dive islands lack.","source":"utilalodge.com, 2026-07-07","si_tag":"safety","accessed":"2026-07-07"},{"q":"Why is Utila the cheapest place to learn to dive?","a":"Utila built its name as the place backpackers came to get certified for a few hundred dollars and never left. A PADI/SSI Open Water course runs roughly US$280–350 — among the cheapest on Earth — with free or discounted dorm accommodation while you dive, on a reef with 60+ dive sites a few fin-kicks off the dock.","source":"alongdustyroads.com, 2026-07-07","si_tag":"liveaboard","accessed":"2026-07-07"},{"q":"Can I dive with the whale sharks, or only snorkel?","a":"Snorkel only — scuba diving with whale sharks is prohibited. As a protected species they are approached from the surface during surface intervals: captains hunt the \"boil/roil\" of feeding fish and diving birds, and you drop off the boat and snorkel beside them. Sightings are probabilistic (best odds Mar–May and Aug–Sep) — market \"best odds,\" never a guarantee.","source":"utilalodge.com, 2026-07-07","si_tag":"expedition","accessed":"2026-07-07"},{"q":"What is there to do on Utila besides diving?","a":"Plenty above the water, all budget-friendly. Take a boat to Water Cay''s uninhabited white-sand sandbar, cold cans at Chepes Beach (the island''s largest public beach), the Utila Cays Garífuna fishing village of Jewel Cay and Pigeon (~500 people on stilt homes over the water), and Freedive Utila — Central America''s first freediving training center — where you learn to fall through the blue on one breath.","source":"islaguru.com, 2026-07-07","si_tag":"tropical","accessed":"2026-07-07"}],"seo":{"meta_title":"Utila Honduras: Cheapest Dive Certs + Whale Sharks Year-Round","meta_description":"Get PADI-certified for ~$300, snorkel with year-round whale sharks, and explore Water Cay and the Mesoamerican reef — Utila is Honduras''s budget-to-boutique dive island. When to go, how to get there, and how to stay safe.","slug":"utila-honduras","primary_keyword":"Utila Honduras diving","long_tail":["cheapest PADI certification Utila","whale sharks Utila snorkel season","how to get to Utila from Roatan La Ceiba ferry","Utila vs Roatan diving budget","Water Cay Utila day trip","Freedive Utila freediving course","Utila hyperbaric chamber dive safety"],"search_language":"es-HN","local_keywords":["buceo Utila","tiburón ballena Utila","curso de buceo Utila","certificación PADI Utila barato","cómo llegar a Utila desde La Ceiba","Cayos de Utila / Water Cay","apnea Utila (freediving)"],"hreflang":["en","es-HN"],"jsonld_type":"TouristDestination","content_freshness":"2026-07-07","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-07-07","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/honduras","read":"2026-08-20T14:48:43Z","source_updated":"2026-07-29T16:40:19+01:00"}]}},"booking":{"advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":[{"si":"liveaboard","status":"live"},{"si":"tropical","status":"live"},{"si":"expedition","status":"live"}],"ultra":[{"name":"Private dive charter / private liveaboard day (out of Utila)","location":"on-Utila waters","posture":"the on-island ultra move is exclusivity on the water, not a hotel - private boat/guide/whale-shark hunt","price_tier":"ultra","earning":"local operator + David''s CLIA dive lane - convert to commissioned agent where offered","mor":"commissionable only where offered; no net-rate resale","source":"https://www.utilalodge.com/"},{"name":"Roatan luxury base (branded/boutique + dive-luxury lodges)","location":"neighboring Bay Island (short ferry/flight)","posture":"the Bay Islands'' actual luxury tier - route ultra client to a Roatan base, day/overnight to Utila for whale sharks","price_tier":"ultra/luxury","earning":"Fora / host-Virtuoso lane - commission on application","mor":"no net-rate resale","source":"https://www.gov.uk/foreign-travel-advice/honduras"},{"name":"Guanaja private-island seclusion","location":"third/quietest Bay Island","posture":"small exclusive private-island/eco-luxury lodges - the no-crowds seclusion play","price_tier":"ultra","earning":"Fora / host-Virtuoso / CLIA - on application","mor":"no net-rate resale","source":"https://www.utilaguide.com/general/utilafaqs/"},{"name":"Utila on-island lodging","posture":"STATED PLAINLY: NO branded ultra on Utila; ceiling = comfortable dive-resort lodge (Utila Lodge / Mango Inn); sell as the whale-shark + dive day to a Roatan/Guanaja ultra base or a private charter","price_tier":"premier (ceiling)","earning":"n/a for ultra","mor":"no net-rate resale","source":"https://www.utilalodge.com/"}],"source_verified":"2026-07-07","hero":{"query":"Utila, Honduras"},"geo":{"lat":16.0983,"lng":-86.935},"orbit":[{"id":"guanaja-honduras","jewels":9,"si":["liveaboard","romance","tropical"]},{"id":"roatan-honduras","jewels":10,"si":["diveglobal","tropical"]}],"orbit_country":[]}'::jsonb, 124)
