  ('uxmal-mexico', '10S', 'Uxmal', 'Mexico', '*If it''s a city the Maya built for the', 'live', 'verified', 'kyoto', 'Yucatán (Mérida & Chichén Itzá)', '{"culture","expedition","culinary"}', '{}', '{"comfort","premier","ultra"}', null, null, '{"key_facts":["UNESCO World Heritage since 1996; Puuc-style Maya capital, flourished 7th-10th c. AD, regional capital c. 850-950 AD","Pyramid of the Magician ~35m/100ft, rounded-corner, five build-phases, solstice-aligned; climbing banned","Open daily 8:00-17:00 (last entry ~16:00); 2026 foreign admission 556 MXN (95 INAH + 461 State)","Ecos de Uxmal light-and-sound show (4K video mapping, 2026), foreign ~748 MXN, Tue/Wed/Fri-Sun","~78 km / ~1h14 south of Mérida via Hwy 261 — a Mérida day-trip; anchor of the Ruta Puuc (Kabah, Sayil, Labná, Xlapak, Loltún)"],"safety":{"emergency_number":"911","nearest_trauma":"Mérida (~1h15 north; regional hospital hub)","air_access_verified":true,"air_access_note":"MID Mérida ~1h15 drive; US nonstops incl. Houston, Miami, Dallas, Atlanta","primary_hazards":["heat/sun exposure (unshaded limestone plazas)","remote Puuc route with limited services","Loltún cave footing (guided-only)","steep Maya risers on Great Pyramid climb","dengue (rainy season)","non-potable tap water"],"climbing_note":"El Adivino climbing BANNED; Great Pyramid climbable north side","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-09-04T12:02:56Z","page_updated":"2026-09-04T00:25:51+01:00","source_country":"mexico","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely","fcdo_zones":[{"name":"The city of Tijuana, in Baja California","lvl":3,"posture":"all-but-essential","except":["airside transit through Tijuana airport","the Cross Border Xpress bridge linking the airport across the border","federal toll road 1D and the Via Rápida through Tijuana to the border"]},{"name":"The city of Te