s"]},{"name":"The state of Zacatecas","lvl":3,"posture":"all-but-essential"},{"name":"In Guanajuato: the areas south-west of road 45D","lvl":3,"posture":"all-but-essential","note":"FCDO advises against all but essential travel to the areas south-west of road 45D. (San Miguel de Allende and Guanajuato City sit outside this area.)"},{"name":"The state of Michoacán","lvl":3,"posture":"all-but-essential","except":["the city of Morelia via federal toll roads 15D, 126 and 43","toll road 48D between Morelia and its airport","the town of Pátzcuaro via toll roads 14D and 15 from Morelia, and boat trips on Lake Pátzcuaro","Federal Highway 15D"]},{"name":"In Jalisco: the areas south and south-west of Lake Chapala to the Colima border","lvl":3,"posture":"all-but-essential","note":"Thirty-nine named municipalities, including Autlán de Navarro, Sayula, Tapalpa, Cocula and Villa Corona — the advisory lists each by name."},{"name":"In Jalisco: eleven northern municipalities","lvl":3,"posture":"all-but-essential","note":"Bolaños, Chimaltitán, Colotlán, Hostotipaquillo, Huejúcar, Huequilla el Alto, Mezquitic, San Martín de Bolaños, Santa María de los Ángeles, Totatiche and Villa Guerrero."},{"name":"The state of Colima","lvl":3,"posture":"all-but-essential","except":["the city of Manzanillo by sea, or by air via Manzanillo-Costalegre International Airport","direct travel via road 200 from that airport to Manzanillo"]},{"name":"The state of Guerrero, including the city of Acapulco","lvl":3,"posture":"all-but-essential","except":["the town of Zihuatanejo/Ixtapa accessed by air"]},{"name":"Within 40km of the Guatemalan border, from the Pacific Coast up to and including the Gracias a Dios crossing","lvl":3,"posture":"all-but-essential"},{"name":"Federal Highway 199 between Rancho Nuevo, outside San Cristóbal de las Casas, and the Chancalá junction outside Palenque","lvl":3,"posture":"all-but-essential","note":"The restriction is the highway segment, not the towns at either end."}]},"timing":{"inflection_curve_start":"late September (winter/dry-season beds harden for Nov-Apr) / early February (Chichen spring-equinox halo)","peak":"dry season Nov-Apr; acute spikes = Chichen spring-equinox halo ~Mar 20-21 (closest boutique-bed base) + Dia de Muertos/Hanal Pixan late Oct-Nov 2","fire_date":"2026-09-14 (winter/dry-season campaign) and 2027-01-25 (spring-equinox halo push) - both curve-start minus 1-2 wks","shoulder":"May + Oct","green":"Jun-Sep (heat/humidity peak, hurricane-season afternoon rain) - cenotes at 9 AM opening","booking_lead":"boutique/casona beds weeks-to-months for Nov-Apr; equinox halo + Dia de Muertos = tight, book months ahead; cenote/Ek Balam/Cuzama tours on-site or a day out","off_season_specials":"green window: position as cool-off cenote base (Zaci/Suytun/Oxman + Cuzama/Homun) + slow-travel colonial alt to hot coast; bundle guided cavern-dive intro","event_peaks":"Dia de Muertos/Hanal Pixan (late Oct-Nov 2) = signature cultural peak; Chichen spring-equinox halo ~Mar 20-21; Semana Santa; Christmas-New Year","note":"sharpen on live tracking - confirm 2026 Hanal Pixan dates + 2027 equinox date; boutique inventory thin, sells out","sources":["https://www.lugaresturisticosenmexico.com/en/valladolid-yucatan-pueblo-magico/","https://thehaphazardtraveler.com/valladolid-yucatan-mexico/","https://www.dreambigtravelfarblog.com/blog/cenote-suytun"]},"jewels":[{"name":"Cenote Zací (in-town)","status":"live","tier":"essential","bookable":"entry on site (free w/ ~100 MXN restaurant) + combo tour","source":"https://cenotesworld.com/en/cenotes-in-Valladolid-Pueblo-Magico-Yucatan/Cenote-Zaci/","timing":"dry season Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"a swimmable sinkhole a 2-min walk from the main square, in a public park; the only in-town cenote, gentlest first-swim","si":"expedition","blurb":"a swimmable sinkhole a 2-min walk from the main square, in a public park; the only in-town cenote, gentlest first-swim","when":"dry season Nov-Apr","commission":"DMC + Viator affiliate (entry non-commissionable)","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["expedition"],"shelf_fit":{"culinary":"destination","culture":"destination","expedition":"primary"},"commission_lane":["DMC","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Cenote Suytun (iconic light-beam)","status":"live","tier":"essential","bookable":"entry ~250 MXN (230 online) + combo tour","source":"https://www.dreambigtravelfarblog.com/blog/cenote-suytun","timing":"dry season Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the region''s most photographed cenote — a single beam of light falls on a central stone platform","si":"expedition","blurb":"the region''s most photographed cenote — a single beam of light falls on a central stone platform","when":"dry season Nov-Apr","commission":"DMC + Viator affiliate","wells":["activities"],"wells_basis":"full pass 2026-10-05, additive — commission lane ''dmc + viator affiliate''","si_all":["expedition"],"shelf_fit":{"culinary":"destination","culture":"destination","expedition":"primary"},"commission_lane":["DMC","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Cenote Oxman (hacienda sinkhole + rope swing)","status":"live","tier":"essential","bookable":"150 MXN (350 w/ pool + lunch)","source":"https://cenotefinder.com/cenotes-in-mexico/valladolid-cenotes/","timing":"dry season Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"deep sinkhole draped in roots on a working hacienda, pool + restaurant, quieter","si":"expedition","blurb":"deep sinkhole draped in roots on a working hacienda, pool + restaurant, quieter","when":"dry season Nov-Apr","commission":"DMC + Viator affiliate","wells":["eat"],"wells_basis":"derived from name/blurb/hook","si_all":["culinary","expedition"],"shelf_fit":{"culinary":"evidenced","culture":"destination","expedition":"primary"},"commission_lane":["DMC","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Cuzamá / Homún cenote country (horse-cart route)","status":"live","tier":"essential","bookable":"on-site cart ~400 MXN (up to 4) + guided day tour; vet operator for animal welfare","source":"https://www.offpathtravels.com/cenotes-cuzama/","timing":"dry season Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"three-cenote railway horse-cart route through the meteor-crater Ring of Cenotes; Homún offers gentler truck/bike alternatives — vet operator for animal welfare","si":"expedition","blurb":"three-cenote railway horse-cart route through the meteor-crater Ring of Cenotes; Homún offers gentler truck/bike alternatives — vet operator for animal welfare","when":"dry season Nov-Apr","commission":"DMC + Viator affiliate","wells":["activities"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["expedition"],"shelf_fit":{"culinary":"destination","culture":"destination","expedition":"primary"},"commission_lane":["DMC","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Guided cavern dive base","status":"live","tier":"comfort","bookable":"professional cave/cavern dive operator (certified guide)","source":"https://travelyucatan.com/cave-and-cenote-diving/","timing":"dry season Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Valladolid/Yucatán interior as a cavern-dive base with certified operators","si":"expedition","blurb":"Valladolid/Yucatán interior as a cavern-dive base with certified operators","when":"dry season Nov-Apr","commission":"dive-operator commission on application + DAN insurance affiliate","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["expedition"],"shelf_fit":{"culinary":"destination","culture":"destination","expedition":"primary"},"commission_lane":["operator","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Ek Balam ruins (climbable acropolis) + Cenote X''Canche","status":"future","tier":"essential","bookable":"~170 MXN cash + guided tour","source":"https://thehaphazardtraveler.com/ek-balam/","timing":"year-round","timing_type":"ALWAYS-ON","hook":"a Maya city 30 min N whose 32 m acropolis you can still climb, with rare intricate stucco façades; X''Canche swim 1.6 km away","si":"culture","blurb":"a Maya city 30 min N whose 32 m acropolis you can still climb, with rare intricate stucco façades; X''Canche swim 1.6 km away","when":"year-round","commission":"DMC + Viator affiliate (entry non-commissionable, cash-only)","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culture"],"shelf_fit":{"culinary":"destination","culture":"primary","expedition":"destination"},"commission_lane":["DMC","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Calzada de los Frailes + San Bernardino convent","status":"future","tier":"essential","bookable":"free walk / guided colonial tour (convent evening sound-and-light)","source":"https://www.lugaresturisticosenmexico.com/en/valladolid-yucatan-pueblo-magico/","timing":"dry season Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the pastel colonial spine of the Pueblo Mágico — a photogenic street of restored façades leading to the 16th-c. convent","si":"culture","blurb":"the pastel colonial spine of the Pueblo Mágico — a photogenic street of restored façades leading to the 16th-c. convent","when":"dry season Nov-Apr","commission":"walking-tour DMC + affiliate","wells":["activities"],"wells_basis":"full pass 2026-10-05, additive — commission lane ''walking-tour dmc + affiliate''","si_all":["culture"],"shelf_fit":{"culinary":"destination","culture":"primary","expedition":"destination"},"commission_lane":["DMC","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Casa de los Venados (folk-art house-museum)","status":"future","tier":"essential","bookable":"donation-entry guided tour","source":"https://www.tripadvisor.com/HotelsNear-g499453-d1863475-Casa_de_los_Venados-Valladolid_Yucatan_Peninsula.html","timing":"year-round","timing_type":"ALWAYS-ON","hook":"a private home + gallery holding 3,000+ pieces of Mexican folk & contemporary art — a singular cultural stop","si":"culture","blurb":"a private home + gallery holding 3,000+ pieces of Mexican folk & contemporary art — a singular cultural stop","when":"year-round","commission":"cultural-tour affiliate (donation non-commissionable)","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culture"],"shelf_fit":{"culinary":"destination","culture":"primary","expedition":"destination"},"commission_lane":["affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Cochinita pibil in its heartland","status":"future","tier":"comfort","bookable":"food-tour + boutique stay","source":"https://cenotefinder.com/cenotes-in-mexico/valladolid-cenotes/","timing":"dry season Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Valladolid is core Yucatecan-cuisine country — slow-roast cochinita pibil, longaniza, marquesitas; pair with a boutique-colonial stay","si":"culinary","blurb":"Valladolid is core Yucatecan-cuisine country — slow-roast cochinita pibil, longaniza, marquesitas; pair with a boutique-colonial stay","when":"dry season Nov-Apr","commission":"food-tour affiliate + host boutique booking","wells":["eat","shop","stay"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["culinary","culture"],"shelf_fit":{"culinary":"primary","culture":"evidenced","expedition":"destination"},"commission_lane":["affiliate"],"commission_embedded":false,"commission_basis":"lane"}],"faq":[{"q":"Which cenotes should I visit from Valladolid?","a":"Start with the three signatures. Zací is a swimmable sinkhole a 2-minute walk from the main square (free with a ~100 MXN restaurant meal) and the gentlest first swim; Suytun (~5 km east, ~250 MXN, open 9 AM–5 PM) delivers the iconic single light-beam onto its stone platform around 1–3 PM; and Oxman (150 MXN, or 350 with pool and lunch) is a deep, root-draped hacienda cenote with a rope swing. The Cuzamá/Homún horse-cart cenote country (~400 MXN/cart) adds a fourth day.","source":"dreambigtravelfarblog.com, 2026-07-06","si_tag":"expedition","accessed":"2026-07-06"},{"q":"Can you climb the ruins at Ek Balam?","a":"Yes — its 32 m acropolis is climbable, which sets Ek Balam apart from Chichén Itzá, where El Castillo has been off-limits since 2008. The site (~30 min north) has rare, intricate stucco façades and a swimmable cenote, X''Canche, 1.6 km away; entry is ~170 MXN, cash only, with no ATM on site.","source":"thehaphazardtraveler.com, 2026-07-06","si_tag":"culture","accessed":"2026-07-06"},{"q":"Is Valladolid a good base for the region?","a":"Yes — it is the mid-peninsula base the buses skip. Founded in 1543 and a Pueblo Mágico since 2012, it sits ~150 km from both Mérida and Cancún, ~40 min from Chichén Itzá, with a real layered bed market of boutique hotels, restored colonial casonas and haciendas — the slow-travel, colonial-romance alternative to the hot coast.","source":"thehaphazardtraveler.com, 2026-07-06","si_tag":"romance","accessed":"2026-07-06"},{"q":"What should I eat in Valladolid?","a":"This is core Yucatecan-cuisine country — slow-roast cochinita pibil, longaniza sausage and marquesita crêpes, amplified during the Hanal Pixán season. It pairs naturally with a boutique-colonial stay and an evening on the Calzada de los Frailes.","source":"cenotefinder.com, 2026-07-06","si_tag":"culinary","accessed":"2026-07-06"},{"q":"What''s the real risk to plan for at the cenotes?","a":"Heat and unguarded water. The cenotes and Ek Balam are best at the 9 AM opening before the heat builds; the cenotes are swim/snorkel with no lifeguards, so use provided life jackets (mandatory posture for non-swimmers and children), shower off sunscreen first, and mind slick stone platforms and rope swings. Drink bottled water only.","source":"dreambigtravelfarblog.com, 2026-07-06","si_tag":"safety","accessed":"2026-07-06"}],"seo":{"meta_title":"Valladolid Mexico 2026: Cenotes Suytun, Zací, Oxman & Ek Balam","meta_description":"Valladolid is a Yucatán Pueblo Mágico + cenote base — swim Zací, Suytun (light beam) and Oxman, climb Ek Balam, walk Calzada de los Frailes. Boutique stays, fees, cenote-dive safety.","slug":"valladolid-mexico","primary_keyword":"Valladolid Yucatán","long_tail":["cenotes Valladolid Suytun Zací Oxman","Cenote Suytun light beam best time","Ek Balam ruins from Valladolid","Valladolid Pueblo Mágico things to do","Cuzamá Homún horse cart cenotes","Valladolid boutique hotels"],"search_language":["en","es-MX"],"local_keywords":["cenotes Valladolid","Cenote Suytun rayo de luz","Cenote Zací Valladolid","Cenote Oxman hacienda","ruinas Ek Balam Valladolid","Valladolid Pueblo Mágico qué hacer","cenotes Cuzamá Homún","Calzada de los Frailes","cochinita pibil Valladolid","hoteles boutique Valladolid"],"hreflang":["en","es-MX"],"jsonld_type":"TouristDestination","content_freshness":"2026-07-06","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-07-06","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-20T14:49:02Z","source_updated":"2026-07-16T16:08:09+01:00"}]}},"booking":{"advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":[{"si":"expedition","status":"live"},{"si":"culture","status":"future"},{"si":"culinary","status":"future"}],"ultra":[{"name":"Coqui Coqui Valladolid (Meson de Malleville)","tier":"premier-luxury BOUTIQUE (straight - design/intimacy/place, not 5-star resort)","why":"wellness/perfumery boutique brand in a colonial property; sell on soul not square footage","earning":"FIT/consortia (Fora/Virtuoso where property participates), commission on application","mor":"host MoR on stay + private tour; cenote/site fees non-commissionable","source":"https://www.tripadvisor.com/HotelsList-Valladolid-Boutique-Hotels-zfp12515607.html"},{"name":"Le Muuch Hotel Boutique","tier":"premier-luxury boutique (21 rooms, boho-chic design)","why":"intimate design boutique in the colonial core","earning":"FIT/consortia, commission on application","mor":"host MoR on stay","source":"https://www.tripadvisor.com/HotelsList-Valladolid-Boutique-Hotels-zfp12515607.html"},{"name":"Chable Yucatan (Merida circuit, ~2 hr W) - nearest TRUE ultra","tier":"ultra-luxury (Leading Hotels of the World)","why":"200-yr San Antonio hacienda, 750 acres, spa beside a sacred cenote, ~30 min from MID; base for private-guided Valladolid/cenote/Ek Balam/Chichen ultra day excursions","earning":"FIT/consortia (Virtuoso/Fora), commission on application","mor":"host MoR on stay + private tour","source":"https://www.lhw.com/hotel/Chable-Yucatan-Chochola-Merida-Mexico"}],"source_verified":"2026-07-06","hero":{"query":"Valladolid, Mexico"},"geo":{"lat":20.6896,"lng":-88.2011},"orbit":[{"id":"celestun-mexico","jewels":6,"si":["expedition","tropical"]},{"id":"chichen-itza-mexico","jewels":7,"si":["culture","expedition","wellness"]},{"id":"izamal-mexico","jewels":8,"si":["culture","romance","culinary"]},{"id":"merida-mexico","jewels":15,"si":["romance","expedition","culture","culinary"]},{"id":"rio-lagartos-mexico","jewels":6,"si":["expedition","tropical"]},{"id":"uxmal-mexico","je