  ('valle-de-guadalupe-mexico', '10S', 'Valle de Guadalupe, Mexico', 'Mexico', 'A Grenache poured at the vine that grew it', 'live', 'verified', 'restaurant', 'Baja California (Valle de Guadalupe & Ensenada)', '{"culinary","expedition"}', '{}', '{"essential","comfort","premier","ultra"}', null, null, '{"key_facts":["Mexico''s premier wine country — 100+ wineries along the Ruta del Vino, producing >90% of Mexican wine.","Baja Med farm-to-table anchors: Deckman''s en el Mogor (Michelin), Fauna, Corazón de Tierra, Finca Altozano.","Fiestas de la Vendimia (August) is the peak: 80+ wineries, 160+ labels, paella competition, pairing dinners.","Design wine-lodges: Banyan Tree Veya (30 villas, on-site Grenache winery), Encuentro/Endémico, Bruma."],"safety":{"emergency":"911","trauma":"Ensenada/Tijuana → San Diego US cross-border evacuation (US-standard trauma care) — a structural cross-border advantage","drink_driving":"always a designated driver / guided wine tour — never self-drive the tasting circuit","rural_road":"Hwy 3 + winery access roads are rural, partly unlit; daylight transfers only, no rural night driving","water":"bottled/filtered","air_access_verified":"Tijuana International (TIJ) via Cross Border Xpress (CBX) pedestrian bridge from San Diego (Otay Mesa), then ~1–1.5 hr drive on Hwy 3; or San Ysidro/Otay Mesa land crossing; Ensenada as coastal gateway. San Diego → Valle ~1h52m + border.","source":"https://www.gov.uk/foreign-travel-advice/mexico","accessed":"2026-07-07","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-09-04T12:02:56Z","page_updated":"2026-09-04T00:25:51+01:00","source_country":"mexico","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely","fcdo_zones":[{"name":"The city of Tijuana, in Baja California","lvl":3,"posture":"all-but-essential","except":["airside transit through Tijuana airport","the Cross B